-- DFY Outbound (CLAUDE.md section 123). Run ONE statement at a time in D1 Studio.
CREATE TABLE IF NOT EXISTS dfy_orders (id TEXT PRIMARY KEY, order_id TEXT NOT NULL, email TEXT NOT NULL, package_name TEXT NOT NULL, monthly_cents INTEGER NOT NULL, ownership INTEGER NOT NULL DEFAULT 0, ownership_cents INTEGER NOT NULL DEFAULT 0, leads INTEGER NOT NULL, initial_sends INTEGER NOT NULL, followups INTEGER NOT NULL, ceiling INTEGER NOT NULL, domains_est TEXT NOT NULL DEFAULT '', inboxes_est TEXT NOT NULL DEFAULT '', reporting TEXT NOT NULL DEFAULT 'monthly', support TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'awaiting_payment', paused_from TEXT NOT NULL DEFAULT '', token_hash TEXT NOT NULL, onboarding_json TEXT NOT NULL DEFAULT '', onboarding_at INTEGER, capacity_json TEXT NOT NULL DEFAULT '', capacity_approved INTEGER NOT NULL DEFAULT 0, ownership_json TEXT NOT NULL DEFAULT '', cycle INTEGER NOT NULL DEFAULT 1, paid_at INTEGER, renews_at INTEGER, reminder_sent_for INTEGER NOT NULL DEFAULT 0, cancel_requested INTEGER NOT NULL DEFAULT 0, note TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE UNIQUE INDEX IF NOT EXISTS dfy_orders_order ON dfy_orders (order_id);
CREATE UNIQUE INDEX IF NOT EXISTS dfy_orders_token ON dfy_orders (token_hash);
CREATE INDEX IF NOT EXISTS dfy_orders_status ON dfy_orders (status, created_at);
CREATE TABLE IF NOT EXISTS dfy_cycles (order_id TEXT PRIMARY KEY, dfy_id TEXT NOT NULL, cycle INTEGER NOT NULL, kind TEXT NOT NULL, amount_cents INTEGER NOT NULL, paid_at INTEGER, created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS dfy_cycles_dfy ON dfy_cycles (dfy_id, cycle);
CREATE TABLE IF NOT EXISTS dfy_events (id INTEGER PRIMARY KEY AUTOINCREMENT, dfy_id TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS dfy_events_order ON dfy_events (dfy_id, id);
CREATE TABLE IF NOT EXISTS dfy_assets (id INTEGER PRIMARY KEY AUTOINCREMENT, dfy_id TEXT NOT NULL, kind TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'planned', verified_at INTEGER, note TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS dfy_assets_order ON dfy_assets (dfy_id, kind);
CREATE TABLE IF NOT EXISTS dfy_metrics (id INTEGER PRIMARY KEY AUTOINCREMENT, dfy_id TEXT NOT NULL, period TEXT NOT NULL, sourced INTEGER NOT NULL DEFAULT 0, verified INTEGER NOT NULL DEFAULT 0, approved INTEGER NOT NULL DEFAULT 0, contacted INTEGER NOT NULL DEFAULT 0, initial_sends INTEGER NOT NULL DEFAULT 0, followup_sends INTEGER NOT NULL DEFAULT 0, failures INTEGER NOT NULL DEFAULT 0, replies INTEGER NOT NULL DEFAULT 0, interested INTEGER NOT NULL DEFAULT 0, optouts INTEGER NOT NULL DEFAULT 0, meetings INTEGER NOT NULL DEFAULT 0, note TEXT NOT NULL DEFAULT '', published INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS dfy_metrics_order ON dfy_metrics (dfy_id, id);
CREATE TABLE IF NOT EXISTS dfy_copy (id INTEGER PRIMARY KEY AUTOINCREMENT, dfy_id TEXT NOT NULL, step INTEGER NOT NULL, kind TEXT NOT NULL, variant TEXT NOT NULL DEFAULT 'A', version INTEGER NOT NULL DEFAULT 1, subject TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft', client_note TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS dfy_copy_order ON dfy_copy (dfy_id, step, variant, version);
